    meta: {
        type: "problem",
        docs: {
            description: "a test file must load the real thing it tests — a first-party module, or the artifact it reads from disk",
        },
        schema: [
            {
                type: "object",
                properties: {
                    firstPartyScopes: { type: "array", items: { type: "string" } },
                },
                additionalProperties: false,
            },
        ],
        messages: {
            noSubjectImport: "This test loads nothing real — no first-party module, and no file read from disk — so nothing here can fail when production code changes. A test that re-implements its subject (`{{subject}}`) proves only that the copy still agrees with itself.",
        },
    },
    create(context) {
        const subject = subjectOf(context.filename);
        if (!subject) {
            return {};
        }
        const firstPartyScopes = context.options[0]?.firstPartyScopes ?? [];
